const qzData=[{"q":"Según Percy Lubbock («The Craft of Fiction», 1921), ¿qué distingue a la escena (scene) del panorama (picture)?","o":["a) Que una tiene diálogo y la otra no","b) Que la escena dramatiza en tiempo real y el panorama resume","c) Que el panorama es siempre mejor","d) Que solo el panorama admite detalles concretos"],"c":1,"e":"Lubbock (1921) nombró la distinción: la escena pone algo frente al lector en tiempo real; el panorama lo resume. No dijo que una fuera siempre mejor que la otra."},{"q":"¿Qué pedía Henry James en los prefacios de la New York Edition (1907-1909)?","o":["a) Dramatizar, dramatizar: poner en escena en vez de resumir","b) Nunca resumir nada","c) Escribir solo panoramas","d) Citar siempre a Chéjov"],"c":0,"e":"James pedía poner en escena en vez de resumir, aunque él mismo resumía cuando le convenía: es práctica declarada, no ley absoluta."},{"q":"¿Qué escribió Antón Chéjov de verdad, en su carta a su hermano Aleksandr del 10 de mayo de 1886?","o":["a) Que en la presa del molino brilló un vidrio de botella como una estrellita","b) Que la luna brilla y hay que mostrarlo","c) Que nunca hay que contar nada","d) Que el panorama es superior"],"c":0,"e":"La carta real, fechada, habla del vidrio de una botella rota brillando en la presa del molino, y de la sombra de un perro o un lobo rodando como una bola."},{"q":"¿Qué es la frase «no me digas que la luna brilla; muéstrame el destello en un vidrio roto»?","o":["a) Una cita textual de Chéjov","b) Una traducción oficial de 1886","c) Una frase de Percy Lubbock","d) Una paráfrasis del siglo XX, sin autor localizable"],"c":3,"e":"Es una paráfrasis popularizada en manuales de taller del siglo XX, sin autor localizable; no son palabras de Chéjov."},{"q":"Según Wayne Booth («The Rhetoric of Fiction», 1961), ¿qué es lo que «muestra, no cuentes» pasa por alto?","o":["a) Que mostrar siempre es superior","b) Que Chéjov nunca escribió cartas","c) Que el autor nunca desaparece del todo; contar es legítimo e inevitable","d) Que el resumen no existe en la ficción"],"c":2,"e":"Booth (1961) sostiene que el autor nunca desaparece del todo, y que contar es una herramienta legítima, no un defecto que haya que eliminar."},{"q":"¿Qué crítica hace Ursula K. Le Guin en «Steering the Craft» (1998) al uso de «show don't tell»?","o":["a) Que hay que mostrarlo todo siempre","b) Que Lubbock se equivocó","c) Que el panorama es un error","d) Que tomada como ley absoluta, mata el resumen necesario y engorda la prosa, porque no se puede mostrar todo"],"c":3,"e":"Le Guin (1998) advierte contra el abuso del dogma: no se puede mostrar todo, y forzarlo engorda la prosa con escenas que no hacía falta dramatizar."},{"q":"¿Qué propone John Gardner en «The Art of Fiction» (1984) sobre la distancia narrativa?","o":["a) Que es un dial que va del resumen lejano al detalle inmediato, no una elección de bien y mal","b) Que siempre hay que estar en el detalle más cercano","c) Que el resumen está prohibido","d) Que la distancia no importa"],"c":0,"e":"Gardner (1984) describe la distancia narrativa como un dial que se gradúa según lo que la escena necesita, no como una elección fija."},{"q":"Según Allan Paivio (1971) y la teoría de la doble codificación, ¿qué se recuerda mejor?","o":["a) Lo abstracto, siempre","b) Las palabras concretas e imaginables, mejor que las abstractas","c) Solo las imágenes, nunca las palabras","d) No hay diferencia"],"c":1,"e":"Paivio (1971) mostró que lo concreto e imaginable se codifica por dos vías (verbal y visual), y por eso se recuerda mejor que lo abstracto."},{"q":"El dial de mostrar y contar de esta etapa tiene tres casillas. ¿Cuáles son?","o":["a) Título, fecha y lugar","b) Presupuesto, elenco y locación","c) Qué se muestra, qué se cuenta, y el detalle que muestra","d) Género, tono y duración"],"c":2,"e":"El dial de esta etapa: qué se muestra (lo que gira), qué se cuenta (lo que conecta) y el detalle que muestra, elegido con cuidado."},{"q":"¿Qué relación hay de verdad entre Chéjov y el aforismo «muestra, no cuentes»?","o":["a) Chéjov lo escribió en un manual de taller","b) Chéjov nunca escribió el aforismo; su linaje crítico es de Lubbock (1921), sobre la práctica de James (1907-1909)","c) Chéjov lo rechazó públicamente en 1898","d) El aforismo es una traducción literal de su obra de teatro"],"c":1,"e":"El linaje real del aforismo va de James (práctica, 1907-1909) a Lubbock (nombre, 1921); Chéjov solo aporta el detalle concreto de su carta de 1886."}];
let qzIdx=0,qzSel=-1,qzDone=false;
