const identifyTaskDB=[{"s":"Distinción entre la escena que dramatiza en tiempo real y el panorama que resume.","type":"Mostrar y contar (Lubbock, 1921)"},{"s":"Pedía poner en escena en vez de resumir, en los prefacios de la New York Edition.","type":"Dramatizar, dramatizar (James, 1907-1909)"},{"s":"El detalle concreto y elegido que, según la carta real de 1886, dice más que un adjetivo abstracto.","type":"El vidrio de botella (Chéjov, 1886)"},{"s":"Sostiene que el autor nunca desaparece del todo y que contar es legítimo.","type":"Wayne Booth (1961)"},{"s":"Advierte que tomar «show don't tell» como ley mata el resumen necesario.","type":"Ursula K. Le Guin (1998)"},{"s":"Describe la distancia narrativa como un dial que se gradúa, no una elección de bien y mal.","type":"John Gardner (1984)"},{"s":"Muestra que las palabras concretas se recuerdan mejor que las abstractas.","type":"Allan Paivio (1971)"},{"s":"Frase atribuida a Chéjov por todas partes, que Chéjov nunca escribió.","type":"La cita fantasma"},{"s":"Herramienta de esta etapa con tres casillas: qué se muestra, qué se cuenta y el detalle que muestra.","type":"El dial de mostrar y contar"},{"s":"Hallazgo replicado sobre el impacto de lo concreto en la comprensión y el recuerdo de un texto.","type":"Sadoski, Goetz y Fritz (1993)"}];
const classifyTaskDB=[{"w":"Mostrar y contar","gen":"Herramienta","n":"Distingue la escena del panorama","g":"Manual de oficio","t":"Lubbock, 1921"},{"w":"Dramatizar, dramatizar","gen":"Práctica declarada","n":"Poner en escena en vez de resumir","g":"Prefacios de novelista","t":"James, 1907-1909"},{"w":"El vidrio de botella","gen":"Detalle concreto","n":"El consejo real, mal citado como aforismo","g":"Carta privada","t":"Chéjov, 1886"},{"w":"Contar es legítimo","gen":"Tesis crítica","n":"El autor nunca desaparece del todo","g":"Teoría literaria","t":"Booth, 1961"},{"w":"La regla mal usada","gen":"Advertencia de taller","n":"No se puede mostrar todo","g":"Manual de taller","t":"Le Guin, 1998"},{"w":"El dial de la distancia","gen":"Herramienta","n":"Va del resumen lejano al detalle inmediato","g":"Manual de oficio","t":"Gardner, 1984"},{"w":"La doble codificación","gen":"Hallazgo","n":"Lo concreto se recuerda mejor que lo abstracto","g":"Psicología cognitiva","t":"Paivio, 1971"},{"w":"El efecto de concreción","gen":"Hallazgo","n":"Lo concreto mejora comprensión y recuerdo del texto","g":"Psicología cognitiva","t":"Sadoski, Goetz y Fritz, 1993"},{"w":"La cita fantasma","gen":"Diagnóstico","n":"Frase sin autor localizable, atribuida a Chéjov","g":"Paráfrasis de taller","t":"Siglo XX, sin autor"},{"w":"El dial de mostrar y contar","gen":"Herramienta práctica","n":"Tres casillas: qué se muestra, qué se cuenta, el detalle","g":"Herramienta de esta casa","t":"Etapa 5"}];
const completeTaskDB=[{"s":"Lubbock distingue la escena del ___.","opts":["panorama","diálogo","vestuario"],"ans":"panorama"},{"s":"James pedía ___, dramatizar, en sus prefacios.","opts":["dramatizar","resumir","narrar"],"ans":"dramatizar"},{"s":"Chéjov escribió su consejo real en una carta de ___.","opts":["1886","1921","1961"],"ans":"1886"},{"s":"La frase de la luna es una ___ del siglo XX.","opts":["paráfrasis","traducción","carta"],"ans":"paráfrasis"},{"s":"Booth sostiene que contar es legítimo e ___.","opts":["inevitable","ilegal","raro"],"ans":"inevitable"},{"s":"Le Guin advierte que no se puede mostrar ___.","opts":["todo","nada","poco"],"ans":"todo"},{"s":"Gardner llama ___ a la distancia narrativa.","opts":["dial","muro","salto"],"ans":"dial"},{"s":"Paivio llamó doble ___ a su teoría de 1971.","opts":["codificación","narración","memoria"],"ans":"codificación"}];
const explainQuestions=[{"q":"Explica la distinción entre mostrar y contar según Percy Lubbock (1921), y por qué Lubbock no dictó «nunca cuentes».","ans":"Percy Lubbock, en «The Craft of Fiction» (1921), nombró la distinción entre la escena (scene), que dramatiza algo en tiempo real frente al lector, y el panorama (picture), que lo resume desde afuera. Lubbock prefería la escena y la defendía como la forma más eficaz de narrar, pero describía el oficio de novelistas como Henry James, no dictaba una ley: su libro es un manual de crítica de oficio, con autor y año, no una orden sin excepciones. Tomar su preferencia personal como «nunca cuentes» es estirar su tesis más allá de lo que él mismo sostuvo."},{"q":"Explica por qué la frase «no me digas que la luna brilla; muéstrame el destello en un vidrio roto» está mal atribuida a Chéjov, y qué escribió Chéjov de verdad en 1886.","ans":"La frase de la luna y el vidrio roto se atribuye a Antón Chéjov en incontables manuales y charlas de escritura, pero Chéjov nunca la escribió: es una paráfrasis del siglo XX, popularizada en los talleres, sin autor localizable. Lo que Chéjov escribió de verdad está en una carta real, fechada, dirigida a su hermano Aleksandr el 10 de mayo de 1886: ahí le aconseja que, para dar una noche de luna, no hace falta nombrarla, sino decir que en la presa de un molino brilló, como una estrellita, un trozo de vidrio de una botella rota, y que la sombra negra de un perro o de un lobo rodó como una bola. El consejo real es más pequeño y más preciso que la frase famosa, y es ese consejo, con su fecha, el que hay que citar."},{"q":"Explica la objeción de Wayne Booth (1961) a la máxima «muestra, no cuentes».","ans":"Wayne Booth, en «The Rhetoric of Fiction» (1961), sostiene que el autor nunca desaparece del todo de un relato, ni siquiera en la prosa más dramatizada: siempre hay una selección, un orden, una voz detrás de lo que se muestra. Por eso Booth defiende que contar es una herramienta legítima e inevitable, no un defecto que haya que eliminar del todo. Su argumento es teoría crítica, un razonamiento sobre cómo funciona la narración, no una medición con datos; pero es la objeción seria que impide tratar «muestra, no cuentes» como una ley sin excepciones."},{"q":"Explica qué crítica hace Ursula K. Le Guin (1998) al uso de «show don't tell» en los talleres de escritura.","ans":"Ursula K. Le Guin, en «Steering the Craft» (1998), advierte que tomar «show don't tell» como una ley absoluta produce el vicio contrario al que se quería corregir: una prosa que dramatiza cada trámite, cada saludo, cada minuto que no gira, y que termina engordando el texto en vez de aclararlo. Le Guin no niega el valor de mostrar; señala que no se puede mostrar todo, y que el resumen sigue haciendo falta para conducir al lector entre los momentos que sí importan. Es un manual de taller con voz de autora, no un hallazgo medido, pero es la advertencia que evita convertir un correctivo útil en una superstición."},{"q":"Explica el dial de mostrar y contar, la herramienta práctica de esta etapa, y sus tres casillas.","ans":"El dial de mostrar y contar es la herramienta que esta etapa deja puesta para el resto de la ruta. Tiene tres casillas: la primera, qué se muestra, es lo que gira (una decisión, una revelación, el beat), y se pone en escena, en tiempo real y con detalle concreto. La segunda, qué se cuenta, es lo que solo conecta un giro con el siguiente (el paso de los días, un trayecto), y se resume, sin dramatizarlo, para no gastar el tiempo del lector. La tercera, el detalle que muestra, es el único detalle concreto y elegido (como el vidrio de botella de Chéjov, 1886) que carga el significado cuando toca mostrar, en vez de describirlo todo o usar un adjetivo abstracto."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra la herramienta ilustrada en cada oración. Escribe al lado de qué herramienta se trata.','<strong>Ejemplo:</strong> El detalle concreto y elegido que dice más que un adjetivo abstracto. → <span style="color:var(--jade);font-weight:700;">El vidrio de botella (Chéjov, 1886)</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y nota.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Nota')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Nota: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
