const evalTFBank=[{"q":"La regla de oro de esta materia exige que toda herramienta se cite con autor y año.","a":true},{"q":"Chéjov escribió la frase «no me digas que la luna brilla; muéstrame el destello en un vidrio roto».","a":false},{"q":"Percy Lubbock publicó «The Craft of Fiction» en 1921.","a":true},{"q":"Henry James pedía dramatizar en vez de resumir, en los prefacios de la New York Edition (1907-1909).","a":true},{"q":"Wayne Booth sostiene que mostrar siempre es superior a contar.","a":false},{"q":"Ursula K. Le Guin advierte que no se puede mostrar todo.","a":true},{"q":"John Gardner describe la distancia narrativa como una elección fija de bien o mal, no un dial.","a":false},{"q":"Allan Paivio propuso la teoría de la doble codificación en 1971.","a":true},{"q":"El efecto de concreción (Sadoski, Goetz y Fritz, 1993) es un hallazgo replicado en psicología cognitiva.","a":true},{"q":"La carta real de Chéjov a su hermano Aleksandr es de 1886.","a":true},{"q":"El dial de mostrar y contar tiene tres casillas: qué se muestra, qué se cuenta y el detalle que muestra.","a":true},{"q":"«Muestra, no cuentes» nace directamente de una carta de Chéjov.","a":false},{"q":"Booth (1961) es una tesis crítica de autor, no una medición.","a":true},{"q":"Le Guin (1998) es un manual de taller con voz de autora.","a":true},{"q":"La cita fantasma de la luna y el vidrio roto tiene un autor localizable y comprobable.","a":false}];
const evalMCBank=[{"q":"¿Qué distingue Percy Lubbock («The Craft of Fiction», 1921) entre escena y panorama?","o":["a) Que solo el panorama admite diálogo","b) Que la escena dramatiza en tiempo real y el panorama resume","c) Que la escena siempre es mejor","d) Que Chéjov las inventó"],"a":1},{"q":"¿Qué pedía Henry James en sus prefacios de 1907 a 1909?","o":["a) Resumir siempre","b) Dramatizar, dramatizar","c) Nunca usar diálogo","d) Citar a Booth"],"a":1},{"q":"¿Qué escribió Chéjov de verdad en su carta a su hermano Aleksandr, el 10 de mayo de 1886?","o":["a) Que la luna brilla y hay que mostrarlo","b) Que en la presa del molino brilló un vidrio de botella como una estrellita","c) Que nunca hay que contar nada","d) Que el panorama es superior"],"a":1},{"q":"¿Qué es la frase «no me digas que la luna brilla; muéstrame el destello en un vidrio roto»?","o":["a) Una cita textual de Chéjov","b) Una traducción oficial de 1886","c) Una frase de Booth","d) Una paráfrasis del siglo XX, sin autor localizable"],"a":3},{"q":"¿Qué objeta Wayne Booth («The Rhetoric of Fiction», 1961) a «muestra, no cuentes»?","o":["a) Que mostrar es imposible","b) Que el autor nunca desaparece del todo; contar es legítimo e inevitable","c) Que Chéjov mintió","d) Que el panorama no existe"],"a":1},{"q":"¿Qué crítica hace Ursula K. Le Guin en «Steering the Craft» (1998)?","o":["a) Que hay que mostrarlo todo siempre","b) Que Lubbock se equivocó","c) Que tomada como ley, la regla mata el resumen necesario y engorda la prosa","d) Que el panorama es un error"],"a":2},{"q":"¿Qué es el dial de la distancia narrativa, de John Gardner (1984)?","o":["a) Va del resumen lejano al detalle inmediato, se gradúa","b) Es una elección única de bien o mal","c) Solo existe en el teatro","d) Es lo mismo que la cita fantasma"],"a":0},{"q":"¿Qué muestra la teoría de la doble codificación de Allan Paivio (1971)?","o":["a) Que lo concreto e imaginable se recuerda mejor que lo abstracto","b) Que todo se olvida igual","c) Que solo las imágenes se recuerdan","d) Que el texto no importa"],"a":0},{"q":"¿Qué es el efecto de concreción (Sadoski, Goetz y Fritz, 1993)?","o":["a) Que lo concreto mejora la comprensión y el recuerdo de un texto","b) Que lo abstracto se recuerda mejor","c) Que no hay diferencia entre concreto y abstracto","d) Que solo aplica al teatro"],"a":0},{"q":"¿Cuáles son las tres casillas del dial de mostrar y contar, la herramienta de esta etapa?","o":["a) Qué se muestra, qué se cuenta, y el detalle que muestra","b) Título, fecha y lugar","c) Presupuesto, elenco y locación","d) Género, tono y duración"],"a":0},{"q":"¿De dónde viene, en realidad, el linaje crítico de «muestra, no cuentes»?","o":["a) De Chéjov, en 1886","b) De Wayne Booth, en 1961","c) De Allan Paivio, en 1971","d) De Percy Lubbock (1921), sobre la práctica de Henry James (1907-1909)"],"a":3},{"q":"¿Qué etiqueta le corresponde a la carta de Chéjov de 1886?","o":["a) Cita fantasma sin autor","b) Manual de taller con voz de autora","c) Consejo real, pero mal citado como aforismo","d) Hallazgo experimental"],"a":2},{"q":"¿Qué etiqueta le corresponde a «The Rhetoric of Fiction» de Booth (1961)?","o":["a) Manual de taller con voz de autora","b) Consejo real mal citado","c) Tesis crítica / argumento teórico","d) Hallazgo replicado"],"a":2},{"q":"¿Qué etiqueta le corresponde a «Steering the Craft» de Le Guin (1998)?","o":["a) Tesis crítica de un teórico","b) Hallazgo experimental replicado","c) Manual de taller con voz de autora","d) Cita fantasma"],"a":2},{"q":"¿Por qué el detalle del vidrio de botella (Chéjov, 1886) importa más que un adjetivo abstracto?","o":["a) Porque es más largo","b) Porque lo dijo Lubbock, no Chéjov","c) Porque los adjetivos siempre mienten","d) Porque un detalle concreto y elegido carga el significado; describirlo todo no es mostrar"],"a":3}];
