// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1886","icon":"✉️","label":"La carta real de Chéjov","text":"El 10 de mayo, Antón Chéjov le escribe a su hermano Aleksandr un consejo de escritura: para dar una noche de luna, no la nombres; di que en la presa del molino brilló, como una estrellita, un trozo de vidrio de una botella rota. <strong>Por qué importa aquí:</strong> es el detalle concreto real de toda la etapa, y la fuente que la cita fantasma desplazó."},{"y":"1907-1909","icon":"🎬","label":"James y «dramatizar, dramatizar»","text":"Henry James escribe los prefacios de la <strong>New York Edition</strong> de sus novelas, donde pide, una y otra vez, poner en escena en vez de resumir. <strong>Por qué importa aquí:</strong> es la práctica real que Lubbock nombraría después; el propio James resumía cuando le convenía."},{"y":"1921","icon":"📖","label":"Lubbock nombra la distinción","text":"Percy Lubbock publica <strong>«The Craft of Fiction»</strong>, donde nombra por primera vez la distinción entre la escena (scene), que dramatiza en tiempo real, y el panorama (picture), que resume. <strong>Por qué importa aquí:</strong> es el linaje crítico real del mandamiento «muestra, no cuentes», que no es de Chéjov."},{"y":"1961","icon":"📚","label":"Booth y la objeción al dogma","text":"Wayne Booth publica <strong>«The Rhetoric of Fiction»</strong>, donde sostiene que el autor nunca desaparece del todo, y que contar es una herramienta legítima e inevitable. <strong>Por qué importa aquí:</strong> es la objeción seria que impide tomar «muestra, no cuentes» como ley sin excepciones."},{"y":"1971","icon":"🧠","label":"Paivio y la doble codificación","text":"Allan Paivio propone la <strong>teoría de la doble codificación</strong>: las palabras concretas e imaginables se recuerdan mejor que las abstractas, porque se guardan por dos vías. <strong>Por qué importa aquí:</strong> explica, desde la psicología cognitiva, por qué el detalle concreto de Chéjov funciona."},{"y":"1984","icon":"🎚️","label":"Gardner y el dial de la distancia","text":"John Gardner publica <strong>«The Art of Fiction»</strong>, donde describe la distancia narrativa como un dial que se gradúa, del resumen lejano al detalle inmediato, y no una elección fija de bien o mal. <strong>Por qué importa aquí:</strong> da el nombre de «dial» que esta etapa adapta para su propia herramienta."},{"y":"1998","icon":"⚠️","label":"Le Guin y la regla mal usada","text":"Ursula K. Le Guin publica <strong>«Steering the Craft»</strong>, donde advierte que tomar «show don't tell» como ley absoluta mata el resumen necesario y engorda la prosa, porque no se puede mostrar todo. <strong>Por qué importa aquí:</strong> es la advertencia que cierra el círculo de esta etapa, contra el dogma."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ============ SIMULACIÓN: EXPLICARLO TODO, «PARA QUE QUEDE CLARÍSIMO» ============
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(mostrarYContar){sfx(mostrarYContar?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(mostrarYContar){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🎬</span><span class="ms-text"><strong>Se mostró el momento del sobre:</strong> quince segundos de video, con la mano temblando, y una frase contando los tres meses de espera antes. Nadie extrañó la explicación completa.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📋</span><span class="ms-text"><strong>Quedó apuntada la razón del reparto:</strong> «se muestra lo que gira, se cuenta lo que conecta», para que la próxima vez no haga falta discutirlo desde cero.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🗣️</span><span class="ms-text"><strong>Se dejó la explicación completa a cámara:</strong> noventa segundos de un alumno diciendo «me sentí feliz, agradecido, emocionado», sin un solo detalle concreto que lo mostrara.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🎬</span><span class="ms-text"><strong>Confundir «que quede clarísimo» con «que se explique todo»</strong> es exactamente el error que esta etapa señala: lo que hace clara una escena no es la cantidad de palabras, es el detalle concreto que se elige. Explicar no siempre aclara; a veces solo alarga.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

