const lectAnalisisBank=[
{q:'¿Por qué la búsqueda de Zaldúa termina en una carta real de 1886 y no en la frase famosa de la luna? Relaciónalo con la idea de que una cita sin fuente es «un rumor con buena reputación».',guia:'Se espera que el lector explique que el cuento distingue entre la fama de una frase y la existencia comprobable de su fuente: la frase de la luna se repite en todas partes, pero nadie la firma con un libro, una carta o una fecha, mientras que el consejo real de Chéjov sí tiene un documento que lo respalda, con destinatario y fecha exacta. La conclusión del cuento (que una cita sin fuente es un rumor con buena reputación) sugiere que la repetición no reemplaza a la comprobación, y que perseguir la fuente, como hace Zaldúa, es la única manera de saber si una frase célebre dice la verdad sobre quien la firma.',t:'Borges'},
{q:'El cuento dice que Zaldúa donó su cuaderno con una nota sobre quien repite una cita sin comprobarla. Explica esa nota con tus palabras, y relaciónala con la regla de oro de esta materia.',guia:'Se espera que el lector recupere la idea de la nota: que repetir una cita sin fuente no es mentir todavía, pero le presta la voz de uno mismo a alguien que quizás nunca dijo eso, y que la única cura es comprobar antes de repetir. Esto se conecta directamente con la regla de oro de esta materia: ninguna herramienta o frase se cita sin autor, año y límite, porque la costumbre de repetir sin comprobar es exactamente el mecanismo que produce las citas fantasma como la de la luna y el vidrio roto.',t:'Borges'},
{q:'Compara cómo Pantoja y Toribio comunican lo mismo (que Pantoja no luchó de verdad) de dos maneras distintas. ¿Cuál muestra y cuál cuenta, y qué efecto tiene cada una en la venta?',guia:'Se espera que el lector identifique que Pantoja CUENTA su hazaña con adjetivos abstractos («valentísimo», «nobilísimo») sin ningún detalle verificable, mientras que Toribio MUESTRA la verdad con un solo detalle concreto (el hilo desteñido de vino en la manga), sin necesidad de explicar nada. El efecto es que el relato de Pantoja convence poco y se desinfla ante la primera pregunta, mientras que el detalle de Toribio convence de inmediato y sin una sola palabra de más, ilustrando la distinción central de la etapa entre explicar y mostrar.',t:'Cervantes'},
{q:'Explica el refrán de Toribio («más vale una mancha bien mirada que cien palabras bien dichas») y relaciónalo con el consejo real de Chéjov sobre el vidrio de botella.',guia:'Se espera que el lector conecte el refrán de Toribio con el consejo de Chéjov (1886): los dos defienden que un solo detalle concreto, bien elegido y bien mostrado, comunica más y de forma más convincente que una acumulación de palabras o adjetivos, por elocuentes que suenen. La mancha de vino y el vidrio de botella cumplen la misma función en sus respectivos textos: son el detalle que carga el significado sin necesidad de que nadie lo explique en voz alta.',t:'Cervantes'},
{q:'Explica, con tus palabras, qué es la doble codificación de Paivio (1971) y por qué el ensayo la relaciona con el peligro de las citas fantasma.',guia:'Se espera que el lector explique que la doble codificación (Paivio, 1971) sostiene que las palabras concretas e imaginables se procesan por dos vías, la verbal y la visual, y por eso se recuerdan mejor que las palabras abstractas, que solo tienen la vía verbal. El ensayo relaciona esto con el peligro de las citas fantasma porque una frase corta, visual y concreta (como la de la luna y el vidrio roto) se vuelve más memorable, y por tanto más citada, que la carta real que la inspiró, aunque la carta sea la fuente verdadera y la frase corta no lo sea.',t:'Harari'},
{q:'El ensayo dice que «mostrar y contar no son enemigos: son las dos herramientas que la misma memoria necesita». Explica esta afirmación con tus propias palabras, usando el argumento del ensayo sobre por qué una mente que solo recuerda lo concreto también necesita resúmenes.',guia:'Se espera que el lector explique que, aunque la memoria retiene mejor lo concreto (Paivio, 1971; el efecto de concreción, Sadoski, Goetz y Fritz, 1993), una mente que tuviera que procesar todo en detalle concreto se saturaría rápidamente, igual que un relato que muestra cada minuto se vuelve ilegible. Por eso la misma memoria que prefiere el vidrio de botella también necesita que se le cuenten, en una línea, los tramos donde no pasó nada relevante, para poder concentrar su atención en lo que sí importa.',t:'Harari'},
{q:'¿Por qué esta entrevista se declara imposible? Explica con las fechas exactas por qué el encuentro nunca pudo ocurrir.',guia:'Se espera que el lector calcule que Antón Chéjov murió en 1904 y que Joaquín Soler Serrano nació en 1919, quince años después: el encuentro es materialmente imposible, y por eso la pieza se declara como entrevista imposible, un género donde la casa presta la voz a alguien que ya no puede hablar, dejando claro que las palabras son invención mientras que la biografía, las obras y las fechas de la persona real son comprobables.',t:'Entrevista'},
{q:'En la entrevista, Chéjov dice que su oficio de médico le enseñó a desconfiar de los síntomas descritos con adjetivos. Explica esa comparación y relaciónala con el consejo real de su carta de 1886.',guia:'Se espera que el lector explique que Chéjov, en la entrevista, compara un síntoma médico vago («me duele mucho») con un síntoma preciso («me duele aquí, cuando respiro hondo»), y traslada esa misma exigencia de precisión a la escritura: un adjetivo abstracto («una noche hermosa») no dice nada verificable, mientras que un detalle concreto (el vidrio que brilla en la presa del molino) sí. La comparación conecta su formación médica con el consejo real de la carta de 1886, mostrando que la exigencia de precisión no nació solo de la literatura.',t:'Entrevista'},
{q:'Explica qué quiere decir Delibes cuando afirma que «se elige el nido, entre todos los detalles posibles, porque ya estaba cargado de sentido antes de que uno lo pusiera ahí». Relaciónalo con la tercera casilla del dial de esta etapa.',guia:'Se espera que el lector explique que Delibes describe el proceso de elegir el detalle concreto: no cualquier objeto sirve, sino aquel que, dentro de la escena, ya tenía un significado latente (el nido vacío, ligado al deseo o a la pérdida) antes de que el autor decidiera nombrarlo. Esto se conecta con la tercera casilla del dial de esta etapa (el detalle que muestra): elegir bien no es describir cualquier cosa, es reconocer cuál de todos los detalles posibles carga ya el significado que la escena necesita.',t:'Quintero y Delibes'},
{q:'Delibes dice que contó, en un párrafo, los años enteros que le llevó a Azarías aprender a querer a la grajilla. Explica por qué esto es un ejemplo de CONTAR bien hecho, y no un defecto.',guia:'Se espera que el lector explique que resumir en un párrafo un proceso de años no es pereza ni un defecto, porque ese tramo solo conecta el estado inicial de Azarías con el vínculo final que sí importa mostrarse después: nadie necesita ver cada uno de esos días para creer en el vínculo, y dramatizarlos todos habría diluido la atención del lector. Es un ejemplo de la segunda casilla del dial (qué se cuenta) aplicada con acierto, coherente con la objeción de Booth (1961) de que contar es legítimo.',t:'Quintero y Delibes'},
{q:'Explica la disputa central del careo entre la defensa y la objeción de «muestra, no cuentes», y por qué la moderación dice que el terreno común es más grande de lo que parece.',guia:'Se espera que el lector explique que la defensa sostiene que la regla funciona como correctivo útil contra el vicio real de sobre-explicar del principiante, apoyada en que lo concreto se recuerda mejor (Paivio, 1971; Sadoski, Goetz y Fritz, 1993), mientras que la objeción, apoyada en Booth (1961) y Le Guin (1998), sostiene que enseñarla como ley produce el vicio contrario, una prosa hinchada de escenas que dramatizan hasta el trámite. El terreno común es más grande de lo esperado porque las dos partes aceptan que el principiante sobre-cuenta, que lo concreto ayuda, y que no se puede mostrar todo; discuten solo si el eslogan hace más bien como correctivo que mal como ley mal citada.',t:'Debate'},
{q:'¿Qué dato concreto propone el careo para acercar la disputa entre mostrar y contar? ¿Por qué ese dato, y no otro, la resolvería mejor?',guia:'Se espera que el lector identifique que el careo propone una comparación, con lectores reales, de un mismo pasaje contado mostrado y contado resumido, midiendo cuál se entiende mejor y cuál se recuerda más, y que explique por qué ese dato (y no una opinión de crítico o de autor) resolvería mejor la disputa: porque mediría el efecto real sobre quien recibe el texto, que es justo lo que las dos posturas dicen defender, en vez de quedarse en el terreno de la preferencia estética o la anécdota de oficio.',t:'Debate'}
];

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue buscando qué se muestra y qué se cuenta!','¡Muy buen trabajo!','¡Ya distingues el detalle concreto del abstracto!','¡Ya sabes cuándo mostrar y cuándo contar!','¡Ninguna cita se te escapa sin su fuente!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🪞 ¡'+name+' completó la Etapa 5 de la Ruta del Hilo que Tira (Mostrar, contar y cuándo cada uno)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

